<template>
<sf-sheet v-if="plan" :open="open" @input="$emit('input',$event)" title="Plan overview" contained :resizable="false" detent="large" content-class="dynamic-plan-sheet">
      <div class="dynamic-plan-detail" :data-plan-id="plan.id">
        <header class="dynamic-plan-detail__heading"><span>{{ plan.goalLabel }}</span><h3>{{ plan.title }}</h3><p>{{ plan.days }} days a week · {{ plan.minutes }} min per session</p></header>
        <section class="dynamic-plan-week" aria-labelledby="dynamic-plan-week-title"><h4 id="dynamic-plan-week-title">Your first week</h4><div class="dynamic-plan-week__days" aria-label="Weekly training schedule"><div v-for="day in plan.firstWeek" :key="day.day" :class="{'is-training':day.training}"><span>{{ day.day }}</span><i>{{ day.training?'•':'–' }}</i></div></div><div class="dynamic-plan-week__sessions"><div v-for="day in trainingDays" :key="day.day"><span>{{ day.day }}</span><div><strong>{{ day.title }}</strong><small>Stage 1 · {{ plan.stages[0].name }}</small></div><b>{{ day.minutes }}<small>min</small></b></div></div></section>
        <section class="dynamic-plan-stages" aria-labelledby="dynamic-plan-stages-title"><h4 id="dynamic-plan-stages-title">How your plan progresses</h4><ol><li v-for="stage in plan.stages" :key="stage.id"><span class="dynamic-plan-stages__number">{{ stage.number }}</span><div><header><strong>{{ stage.name }}</strong><span>{{ stage.period }}</span></header><p>{{ stage.focus }}</p></div></li></ol></section>
        <button  type="button" class="dynamic-plan-adjust" @click="adjust"><sf-icon name="coach" :size="17"/>Adjust with AI Coach<sf-icon name="arrow" :size="15"/></button>
      </div>
      <template #footer><sf-button @click="activate">Activate Plan</sf-button><p class="dynamic-plan-access">{{ member.active?'Included with Premium':'Premium required to activate' }}</p></template>
    </sf-sheet>
</template>
<script>
import {SfIcon,SfButton,SfSheet} from '@/design-system'
export default {
  components:{SfIcon,SfButton,SfSheet},model:{prop:'open',event:'input'},props:{open:Boolean,plan:Object,member:Object},
  computed:{trainingDays(){return this.plan?.firstWeek.filter(day=>day.training)||[]}},
  methods:{activate(){this.$emit('input',false);this.$emit('action','activate-plan:'+this.plan.id)},adjust(){this.$emit('input',false);this.$emit('action','discuss-plan:'+this.plan.id)}}
}
</script>
